(()=>{
  const $=id=>document.getElementById(id);
  const esc=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
  const words=[
    {en:"habitat",vi:"môi trường sống",icon:"🌲",meaning:"the natural home of a plant or animal"},
    {en:"lodge",vi:"tổ hải ly",icon:"🛖",meaning:"a beaver's home, often with an underwater entrance"},
    {en:"wetland",vi:"vùng đất ngập nước",icon:"🌿",meaning:"land that stays covered or filled with water"},
    {en:"erosion",vi:"sự xói mòn",icon:"🌊",meaning:"the wearing away of soil by water or wind"},
    {en:"silt",vi:"phù sa",icon:"🟤",meaning:"fine soil carried and left behind by water"}
  ];
  const copy={
    0:{en:"A strange signal is coming from an Earth wetland. Meet Nilo, our alien field scientist, and discover why one small animal can reshape an entire habitat.",vi:"Một tín hiệu lạ đang phát ra từ vùng đất ngập nước trên Trái Đất. Hãy gặp Nilo, nhà khoa học thực địa ngoài hành tinh, và khám phá vì sao một loài vật nhỏ có thể làm thay đổi cả môi trường sống."},
    1:{en:"Learn five field words before we enter the wetland. Tap each card to reveal its meaning.",vi:"Học năm từ dùng trong chuyến khảo sát trước khi bước vào vùng đất ngập nước. Chạm vào từng thẻ để xem nghĩa."},
    2:{en:"The stream was shallow and fast. A beaver placed branches, stones and mud across it. Water collected behind the dam and formed a deeper, calmer pond. The beaver built a lodge in the pond, with an entrance below the water. The pond helps protect the beaver from many land predators and provides food nearby. It also creates wetland habitat for other living things. However, a dam can flood nearby land and change the flow of water.",vi:"Dòng suối ban đầu nông và chảy nhanh. Một con hải ly xếp cành cây, đá và bùn chắn ngang dòng nước. Nước tích tụ phía sau đập và tạo thành một hồ sâu, yên hơn. Hải ly xây tổ trong hồ, có lối vào nằm dưới mặt nước. Hồ giúp bảo vệ hải ly khỏi nhiều loài săn mồi trên cạn và tạo nguồn thức ăn gần đó. Hồ cũng tạo môi trường đất ngập nước cho các sinh vật khác. Tuy nhiên, đập có thể làm ngập vùng đất gần đó và thay đổi dòng chảy."},
    3:{en:"What changed after the beaver blocked the stream?",vi:"Điều gì đã thay đổi sau khi hải ly chặn dòng suối?"},
    4:{en:"Why is an underwater lodge entrance useful to a beaver?",vi:"Vì sao lối vào tổ nằm dưới nước lại hữu ích với hải ly?"},
    5:{en:"Nilo detected a hidden Wetland Core near the dam. Search the scene and collect it for the laboratory.",vi:"Nilo phát hiện một Lõi Đất Ngập Nước ẩn gần con đập. Hãy tìm trong bức hình và thu thập nó cho phòng thí nghiệm."}
  };
  let ctx;
  function s(){return ctx.state.science}
  function persist(){ctx.save();ctx.updateHud()}
  function go(view,step){s().view=view;if(step!==undefined)s().step=step;persist();render()}
  function translateButton(step){if(!copy[step])return"";const seen=s().translated.includes(step),locked=ctx.state.human.shield<1&&!seen;return `<button class="science-translate" id="scienceTranslate" ${locked||seen?"disabled":""}>${seen?"✓ Vietnamese shown":locked?"🔒 Translate · Need 1 Shield":"Translate · −1 Shield"}</button>`}
  function bindTranslate(step){const button=$("scienceTranslate");if(!button)return;button.onclick=()=>{if(!s().translated.includes(step)&&ctx.state.human.shield>0){ctx.state.human.shield--;s().translated.push(step);persist();render()}}}
  function bilingual(step){return `<p class="science-lead">${esc(copy[step].en)}</p>${s().translated.includes(step)?`<p class="science-vi" lang="vi">${esc(copy[step].vi)}</p>`:""}`}
  function renderLab(){const complete=s().completed;ctx.view.innerHTML=`<section class="science-lab-screen"><div class="science-lab-hero"><div class="science-lab-copy"><p class="science-kicker">EARTH DISCOVERY LAB</p><h1>Explore Earth.<br><span>Repair the lab.</span></h1><p>Follow alien scientists into Earth's hidden worlds. Every discovery unlocks real science and upgrades this laboratory.</p><div class="science-lab-stats"><span>🔬 Lab level <b>${s().labLevel}</b></span><span>💎 Knowledge crystals <b>${s().crystals}</b></span><span>🧭 Discoveries <b>${s().discoveries.length}</b></span></div></div></div><div class="science-worlds"><article class="science-world-card available"><div class="world-art"><img src="assets/science-beaver-wetland-v1.png" alt="Nilo exploring a beaver wetland"></div><div><p class="science-kicker">BIO WORLD · WETLAND SIGNAL</p><h2>Why do beavers build dams?</h2><p>Meet Nilo, learn 5 field words, follow the wetland story and recover a hidden sample.</p><ul><li>⏱ 5–7 minutes</li><li>🗣 English first · A2–B1</li><li>💎 Knowledge Crystal</li></ul><button id="startScienceLesson">${complete?"Explore again":"Start expedition"} →</button></div></article><article class="science-world-card locked"><span>🔒</span><h3>Micro World</h3><p>Coming later</p></article><article class="science-world-card locked"><span>🔒</span><h3>Weather World</h3><p>Coming later</p></article></div></section>`;$("startScienceLesson").onclick=()=>{s().cardsSeen=[];s().answers={};s().feedback="";s().hintDepth=0;s().hiddenFound=false;go("lesson",0)}}
  function lessonShell(body,step,actions=""){ctx.view.innerHTML=`<section class="science-lesson-screen"><div class="science-progress"><button id="scienceBack">← Lab</button><div><span style="--science-progress:${Math.round((step+1)/7*100)}%"></span></div><strong>${step+1}/7</strong></div><article class="science-lesson-card">${body}<div class="science-actions">${translateButton(step)}${actions}</div></article></section>`;$("scienceBack").onclick=()=>go("lab");bindTranslate(step)}
  function nextButton(step,label="Continue →"){return `<button class="science-primary" id="scienceNext">${label}</button>`}
  function renderIntro(){lessonShell(`<div class="science-story-grid"><img src="assets/science-beaver-wetland-v1.png" alt="Alien scientist Nilo observing a beaver dam"><div><p class="science-kicker">FIELD LOG 01 · EARTH</p><h1>Wetland Signal</h1>${bilingual(0)}<div class="nilo-message"><span>👽</span><p><strong>Nilo:</strong> “My scanner says this beaver changed the stream. Let’s find out how—and why!”</p></div></div></div>`,0,nextButton(0,"Meet Nilo →"));$("scienceNext").onclick=()=>go("lesson",1)}
  function renderFlashcards(){const all=s().cardsSeen.length===words.length;lessonShell(`<p class="science-kicker">FIELD WORDS</p><h1>Pack your science vocabulary</h1>${bilingual(1)}<div class="science-flashcards">${words.map((word,i)=>`<button class="science-flashcard ${s().cardsSeen.includes(i)?"seen":""}" data-card="${i}"><span class="word-icon">${word.icon}</span><strong>${word.en}</strong><small>${s().cardsSeen.includes(i)?`${word.meaning}<em>${word.vi}</em>`:"Tap to reveal"}</small></button>`).join("")}</div><p class="science-note">${all?"Field kit ready!":"Open all 5 cards to continue."}</p>`,1,nextButton(1));document.querySelectorAll("[data-card]").forEach(card=>card.onclick=()=>{const i=Number(card.dataset.card);if(!s().cardsSeen.includes(i))s().cardsSeen.push(i);persist();render()});$("scienceNext").disabled=!all;$("scienceNext").onclick=()=>go("lesson",2)}
  function renderStory(){lessonShell(`<p class="science-kicker">ILLUSTRATED STORY</p><h1>A small builder, a big change</h1><div class="science-story-picture"><img src="assets/science-beaver-wetland-v1.png" alt="A beaver building a dam that creates a wetland pond"><span class="story-label dam">dam</span><span class="story-label lodge">lodge</span><span class="story-label wetland">wetland</span></div>${bilingual(2)}<div class="cause-chain"><span>Fast stream</span><b>→</b><span>Dam slows water</span><b>→</b><span>Deep pond</span><b>→</b><span>Safer lodge + wetland</span></div>`,2,nextButton(2,"Investigate →"));$("scienceNext").onclick=()=>go("lesson",3)}
  const questions={3:{choices:["A deeper, calmer pond formed.","The stream became completely dry.","All the trees disappeared."],right:0,why:"The dam slows the water, so water collects behind it and forms a pond.",hint1:"Look at the water behind the branches.",hint2:"A barrier slows flowing water and makes it collect."},4:{choices:["It helps hide and protect the beaver from land predators.","It makes the lodge warmer by adding sunlight.","It allows trees to grow inside the lodge."],right:0,why:"The beaver can swim into its lodge while many land predators cannot easily follow.",hint1:"Think about which animals can follow the beaver underwater.",hint2:"The entrance is a protected route between the pond and the lodge."}};
  function renderQuestion(step){const q=questions[step],answer=s().answers[step];lessonShell(`<p class="science-kicker">THINK LIKE A SCIENTIST · ${step-2}/2</p><h1>${esc(copy[step].en)}</h1>${s().translated.includes(step)?`<p class="science-vi" lang="vi">${esc(copy[step].vi)}</p>`:""}<div class="science-choices">${q.choices.map((choice,i)=>`<button data-choice="${i}" class="${answer===i?"selected":""}"><span>${String.fromCharCode(65+i)}</span>${esc(choice)}</button>`).join("")}</div><p class="science-feedback ${s().feedback.startsWith("Correct")?"good":""}">${esc(s().feedback)}</p>${s().hintDepth?`<div class="science-hint"><strong>${s().hintDepth===1?"Nilo's clue":"Deeper clue"}</strong><p>${esc(s().hintDepth===1?q.hint1:q.hint2)}</p></div>`:""}`,step,`<button class="science-secondary" id="scienceHint">${s().hintDepth===0?"Hint 1 · Free":s().hintDepth===1?(ctx.state.human.shield?"Deeper hint · −1 Shield":"🔒 Deeper hint · Need 1 Shield"):"Hint opened"}</button>${s().feedback.startsWith("Correct")?nextButton(step):""}`);document.querySelectorAll("[data-choice]").forEach(button=>button.onclick=()=>{const chosen=Number(button.dataset.choice);s().answers[step]=chosen;if(chosen===q.right){s().feedback=`Correct! ${q.why}`}else{s().feedback="Not yet. Nothing was lost—use the evidence and try again."}persist();render()});$("scienceHint").onclick=()=>{if(s().hintDepth===0)s().hintDepth=1;else if(s().hintDepth===1&&ctx.state.human.shield>0){ctx.state.human.shield--;s().hintDepth=2}persist();render()};if($("scienceNext"))$("scienceNext").onclick=()=>{s().feedback="";s().hintDepth=0;go("lesson",step+1)}}
  function renderSearch(){lessonShell(`<p class="science-kicker">HIDDEN DISCOVERY</p><h1>Find the Wetland Core</h1>${bilingual(5)}<div class="science-search-scene ${s().hiddenFound?"found":""}"><img src="assets/science-beaver-wetland-v1.png" alt="Search the wetland scene for a hidden sample"><button id="wetlandCore" aria-label="Hidden Wetland Core"><i>◆</i></button>${s().hiddenFound?`<div class="sample-found"><span>💎</span><strong>Wetland Core found!</strong><small>Sample recorded in the lab.</small></div>`:""}</div><p class="science-note">${s().hiddenFound?"Excellent observation. The sample stores evidence about water, soil and living things.":"Look closely near the flowing water below the dam."}</p>`,5,s().hiddenFound?nextButton(5,"Return to the lab →"):"");$("wetlandCore").onclick=()=>{s().hiddenFound=true;persist();render()};if($("scienceNext"))$("scienceNext").onclick=completeLesson}
  function completeLesson(){s().completed=true;s().labLevel=Math.max(1,s().labLevel);s().crystals=Math.max(1,s().crystals);if(!s().discoveries.includes("Beaver wetland"))s().discoveries.push("Beaver wetland");if(!ctx.state.inventory.includes("Wetland Core"))ctx.state.inventory.push("Wetland Core");if(!ctx.state.inventory.includes("Knowledge Crystal"))ctx.state.inventory.push("Knowledge Crystal");s().step=6;persist();render()}
  function renderComplete(){lessonShell(`<div class="science-complete"><div class="upgrade-burst" aria-hidden="true">✦</div><p class="science-kicker">EXPEDITION COMPLETE</p><h1>Earth Lab upgraded!</h1><p>You explained how a beaver dam can form a pond, protect a lodge and create wetland habitat.</p><div class="science-rewards"><span>💎<b>Knowledge Crystal</b></span><span>◆<b>Wetland Core</b></span><span>🔬<b>Living Habitat · Level 1</b></span></div><div class="lab-upgrade"><img src="assets/science-earth-lab-v1.png" alt="Earth Discovery Lab upgraded with a living habitat station"><i></i></div></div>`,6,`<button class="science-secondary" id="scienceReplay">Replay lesson</button><button class="science-primary" id="scienceFinish">Explore the lab →</button>`);$("scienceReplay").onclick=()=>{s().cardsSeen=[];s().answers={};s().feedback="";s().hintDepth=0;s().hiddenFound=false;go("lesson",0)};$("scienceFinish").onclick=()=>go("lab")}
  function renderLesson(){({0:renderIntro,1:renderFlashcards,2:renderStory,3:()=>renderQuestion(3),4:()=>renderQuestion(4),5:renderSearch,6:renderComplete}[s().step]||renderIntro)()}
  function render(){if(!ctx)return;s().view==="lesson"?renderLesson():renderLab()}
  window.ScienceDiscovery={render(context){ctx=context;render()}};
})();
